---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Thinking: The live trace, written as the agent works, then folded away.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change thinking.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './thinking.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="thinking" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tk" data-open="1">
  <button class="tk-h" aria-expanded="true">
    <span class="tk-mark"><span class="think on"><i></i><i></i><i></i><i></i></span></span>
    <span class="tk-title shim">Checking the pricing page</span><span class="tk-time num">0s</span>
    <svg class="i xs tk-chev"><use href="#i-chev-d"/></svg>
  </button>
  <div class="fold tk-fold"><div><ol class="tk-list" aria-live="polite"></ol></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './thinking.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Thinking ---------- */
/* the steps the agent takes, on a line that turns green as each one finishes; the step in hand turns in the accent with a
   soft halo, and what each step found writes itself in under it. The header ends as a summary of the work */
/* neither the trace nor the box it sits in anchors the page's scroll: a centred demo that grows would otherwise pull
   the page along with it */
.stage-in:has(>.tk){overflow-anchor:none}
.tk{font-size:14px;width:100%;max-width:420px;margin-inline:auto;overflow-anchor:none}
/* on a card the trace keeps the room it will fill, so the header stays put as steps arrive */
.stage-in>.tk{min-height:inherit}
.tk-h{display:flex;align-items:center;gap:10px;width:calc(100% + 16px);margin:0 -8px;padding:6px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));text-align:left;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.tk-h:hover{background:var(--dm-row)}}
.tk-mark{width:18px;height:18px;flex:none;display:grid;place-items:center;color:var(--dm-accent-mark,var(--dm-accent));transition:color .3s}
.tk-h.tk-fin .tk-mark{color:var(--dm-ok)}
.tk-h.tk-fin .tk-mark .i{animation:tkpop .5s var(--dm-ease) backwards}
.tk-title{flex:1;min-width:0;color:var(--dm-fg)}
.tk-time{color:var(--dm-muted);font-size:13px}
.tk-chev{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.tk[data-open="0"] .tk-chev{transform:rotate(-90deg)}
.tk-list{list-style:none;margin:0;padding:6px 0 0;display:flex;flex-direction:column}
.tk-st{position:relative;display:flex;gap:10px;padding:6px 0}
/* the line from each step down to the next: grey, and green once the step above it is done */
.tk-st:not(:last-child)::before,.tk-st.done:not(:last-child)::after{content:"";position:absolute;left:8.25px;top:29px;bottom:-5px;width:1.5px;border-radius:1px;background:var(--dm-line)}
.tk-st.done:not(:last-child)::after{background:color-mix(in srgb,var(--dm-ok) 55%,var(--dm-line));transform-origin:top;animation:tkgrow .6s var(--dm-ease) backwards}
@keyframes tkgrow{from{transform:scaleY(0)}}
.tk-st .mk{position:relative;width:18px;height:18px;flex:none;margin-top:1px;display:grid;place-items:center;border-radius:50%;color:var(--dm-muted);transition:background .32s,color .32s}
.tk-st .mk .spin{width:10px;height:10px}
.tk-st.run .mk{color:var(--dm-accent-mark,var(--dm-accent));background:var(--dm-accent-bg);animation:tkhalo 1.8s var(--dm-ease-io) infinite}
.tk-st.done .mk{background:var(--dm-ok-bg);color:var(--dm-ok)}
.tk-st.done .mk .i{animation:tkpop .45s var(--dm-ease) backwards}
.tk-st.retry .mk{background:var(--dm-warn-bg);color:var(--dm-warn);animation:tkhalow 1.8s var(--dm-ease-io) infinite}
@keyframes tkhalo{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
@keyframes tkhalow{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
@keyframes tkpop{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:none}}
.tk-st .tx{flex:1;min-width:0;display:flex;flex-direction:column}
.tk-st .tk-ln{display:flex;align-items:baseline;gap:var(--dm-s-2)}
.tk-st .lab{flex:1;min-width:0;color:var(--dm-fg);transition:color .32s}
.tk-st.done .lab{color:var(--dm-fg2)}
/* how long the step took, once it is done */
.tk-st .tk-dur{flex:none;font-size:12px;color:var(--dm-muted)}
/* what a step found opens under it, a word at a time */
.tk-st .res{display:grid;grid-template-rows:0fr;font-size:13px;color:var(--dm-muted);transition:grid-template-rows .32s var(--dm-ease),color .32s}
.tk-st .res.on{grid-template-rows:1fr}
.tk-st .res>span{overflow:hidden;min-height:0}
.tk-st .res .w{display:inline-block;white-space:pre;animation:tkword .42s var(--dm-ease) backwards}
@keyframes tkword{from{opacity:0;transform:translateY(3px);filter:blur(2px)}}
.tk-st.retry .res{color:var(--dm-warn)}
.tk-st .res [data-tip]{text-decoration:underline dotted var(--dm-faint);text-underline-offset:3px;cursor:default}
:root:not([data-style="soft"]) .tk-st.run .mk:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .tk-st.retry .mk:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .tk-st.run .mk:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px var(--dm-accent-mark)}
:root:not([data-style="soft"]) .tk-st.done:not(:last-child):not(:where([data-style="soft"],[data-style="soft"] *))::after{background:var(--dm-ok);width:1px;left:8.5px}
:root:not([data-style="soft"]) .tk-st:not(:last-child):not(:where([data-style="soft"],[data-style="soft"] *))::before{width:1px;left:8.5px;background:repeating-linear-gradient(var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .tk-st.done .mk .i:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .tk-h.tk-fin .tk-mark .i:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .tk-st .res .w:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpin .3s var(--dm-ease) backwards}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, enter, html, swap, tip } from '../core/core.js';
DM.def('thinking', (r, c) => {
  const tk = $('.tk', r), list = $('.tk-list', r), title = $('.tk-title', r), time = $('.tk-time', r), head = $('.tk-h', r), fold = $('.tk-fold', r), mark = $('.tk-mark', r);
  // each step: what the agent does and what it found. Measuring the cards times out once, counts down and tries again
  const S = [
    ['Open Pricing v4 in Figma', '6 frames, 3 plan cards', 1300],
    ['Read the spacing tokens', 'tokens.css, 9 spacing values', 1200],
    ['Measure the plan cards', '3 cards are off the 8px grid', 1400, { retry:"Figma didn't answer", tip:'Pro has an 18px gap, Team 22px and Enterprise 13px' }],
    ['Check text contrast', 'All 14 text pairs pass AA', 1100],
    ['Plan the fix', '2 changes, about 3 minutes', 1200]
  ];
  const setOpen = o => { tk.dataset.open = o ? '1' : '0'; fold.classList.toggle('shut', !o); head.setAttribute('aria-expanded', o); };
  head.onclick = () => setOpen(tk.dataset.open !== '1');
  // the line under a step opens and then crossfades; what the step found writes itself in a word at a time, and a tip on it
  // holds the detail
  const words = t => t.split(' ').map((w, i, a) => `<span class="w" style="animation-delay:${i * 45}ms">${w}${i < a.length - 1 ? ' ' : ''}</span>`).join('');
  const note = (li, text, tip, found) => { const res = $('.res', li), sp = res.firstElementChild; res.classList.add('on');
    if (found){ sp._sw = null; sp.classList.remove('out'); sp.innerHTML = tip ? `<span data-tip="${tip}">${words(text)}</span>` : words(text); }
    else swap(sp, text); };
  const glyph = (li, g) => { const mk = $('.mk', li); mk.innerHTML = g; enter(mk.firstElementChild); };
  let secs = 0, live = true; c.every(1000, () => { if (live){ secs++; time.textContent = secs + 's'; } });
  c.run(async () => {
    await c.wait(600);
    for (const [lab, res, ms, x] of S){
      const li = html(`<li class="tk-st run"><span class="mk"><span class="spin"></span></span><div class="tx"><span class="tk-ln"><span class="lab shim">${lab}</span><span class="tk-dur num"></span></span><span class="res"><span></span></span></div></li>`);
      list.appendChild(li); enter(li);
      const l = $('.lab', li); let took = ms;
      await c.wait(ms);
      if (x && x.retry){
        li.classList.replace('run', 'retry'); l.classList.remove('shim'); glyph(li, I('clock','xs'));
        for (let k = 2; k > 0; k--){ note(li, `${x.retry}. Trying again in ${k}s`); await c.wait(1000); }
        li.classList.replace('retry', 'run'); l.classList.add('shim'); glyph(li, '<span class="spin"></span>'); note(li, 'Trying again'); await c.wait(900); took += 2900;
      }
      li.classList.replace('run', 'done'); l.classList.remove('shim'); glyph(li, I('check','xs')); note(li, res, x && x.tip, true);
      const t = $('.tk-dur', li); t.textContent = (took / 1000).toFixed(1) + 's'; enter(t);
    }
    // the header becomes what the work came to, and folds the trace away
    await c.wait(500); live = false;
    head.classList.add('tk-fin'); mark.innerHTML = I('ok'); enter(mark.firstElementChild); title.classList.remove('shim'); swap(title, '3 cards to fix, 2 changes planned');
    await c.wait(2000); setOpen(false);
  });
  // the preview's story: once it has folded, the person opens it again and reads what the cards measured
  if (r === c.st) c.story(async s => {
    await s.until(() => fold.classList.contains('shut')); await s.beat(2);
    await s.tap(head); await s.beat(2);
    await s.point($('.res [data-tip]', list)); await s.beat(3);
    s.away(); await s.beat(1);
  });
});
